const content = `
  <div class="flexcol">
    <h3>Rerolling a Saving Throw:</h3>
    <p>Please pick a saving throw to reroll from the buttons below.</p>
  </div>
`;

const labels = [game.i18n.localize("PF1.SavingThrowFort"), game.i18n.localize("PF1.SavingThrowRef"), game.i18n.localize("PF1.SavingThrowWill")];

async function getAnswer() {
  return Dialog.wait({
    title: `${item.name} – Reroll a Saving Throw`,
    content: content,
    buttons: {
      fort: {
        label: labels[0],
        callback: () => "fort",
      },
      ref: {
        label: labels[1],
        callback: () => "ref",
      },
      will: {
        label: labels[2],
        callback: () => "will",
      }
    },
    default: 'fort',
    close: () => null,
  },
  {
     height: "auto",
     width: 680,
  });
}

const answer = await getAnswer();
if(answer !== null) {
  actor.rollSavingThrow(answer);
} else {
  ui.notifications.warn(`No answer was selected. Restoring use of "${item.name}".`);
  await item.update({"system.uses.value": 1 });
}

async function getAnswer() {
  let buttons = {};
  let content = `
  <div class="flexcol">
    <h3>Rerolling a Check:</h3>
    <p>Please pick an attack or skill check to reroll from the buttons below.</p>
  `;

  buttons["melee"] = {
    label: game.i18n.localize("PF1.Melee"),
    callback: () => "melee"
  }
  buttons["ranged"] = {
    label: game.i18n.localize("PF1.Ranged"),
    callback: () => "ranged"
  }
  buttons["cmb"] = {
    label: game.i18n.localize("PF1.CMBAbbr"),
    callback: () => "cmb"
  }

  // Skill checks
  actor.allSkills.forEach( skl => {
    const skill = actor.getSkillInfo(skl).fullName;
    buttons[skl] = {
      label: skill,
      callback: () => skl
    }
  });

  return Dialog.wait({
    title: `${item.name} – Reroll an Attack or Skill check`,
    content: content,
    buttons: buttons,
    default: null,
    close: () => null,
  },
  {
     height: "auto",
     width: 680,
  });
}

const answer = await getAnswer();
if(answer === null) {
  ui.notifications.warn(`No answer was selected. Restoring use of "${item.name}".`);
  await item.update({"system.uses.value": 1 });
} else {
  switch(answer) {
    case "melee": {
      await actor.rollAttack();
      break;
    }
    case "ranged": {
      await actor.rollAttack({ ranged: true });
      break;
    }
    case "cmb": {
      await actor.rollAttack({ maneuver: true });
      break;
    }
    default:
        await actor.rollSkill(answer);
  }
}
